-- Новые вопросы тем 09–12 (близко к лекциям и практике курса DBA1) с пояснениями к каждому варианту.
-- Повторный запуск безопасен: вопрос с тем же текстом не добавляется второй раз.

BEGIN;

INSERT INTO questions (category_id, question_text, options, correct_answer, explanation, option_notes)
SELECT n.* FROM (
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '09.'), 'Допишите команду psql, чтобы видеть запросы к системному каталогу, которые выполняют команды вроде \d+:
```
\set ___ on
```', '{"A":"`ECHO_HIDDEN`","B":"`QUIET`","C":"`VERBOSITY`","D":"`ECHO`"}'::jsonb, 'A', 'В практике курса так выясняют, какие запросы выполняет команда \d+ pg_views.', '{"A":"Показывает запросы, которые psql скрыто выполняет для команд с обратной косой чертой.","B":"Подавляет информационные сообщения psql.","C":"Задаёт подробность сообщений об ошибках.","D":"Управляет выводом команд, которые отправляются на сервер, но не скрытых запросов команд \\d."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '09.'), 'Допишите команду psql, чтобы получить список схем вместе с системными:
```
\dn___
```', '{"A":"`S`","B":"`x`","C":"`+`","D":"`t`"}'::jsonb, 'A', 'Без модификатора S команды \d показывают только пользовательские объекты.', '{"A":"Модификатор S добавляет в список системные объекты.","B":"Такого модификатора у \\dn нет; \\x — отдельная команда формата вывода.","C":"Добавляет подробности, например права и описание, но системные схемы не показывает.","D":"Такого модификатора у \\dn нет."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '09.'), 'Допишите команду psql, чтобы получить список всех представлений схемы information_schema:
```
\dv ___
```', '{"A":"`information_schema%`","B":"`information_schema`","C":"`*.information_schema`","D":"`information_schema.*`"}'::jsonb, 'D', 'Это одно из заданий практики курса.', '{"A":"В шаблонах psql используется *, а не %.","B":"Это шаблон имени представления, а не схемы.","C":"Ищет во всех схемах представления с именем information_schema.","D":"Шаблон схема.* выбирает все представления этой схемы."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '09.'), 'Что появилось у большинства таблиц системного каталога начиная с PostgreSQL 14?', '{"A":"Триггеры на изменение","B":"Секционирование","C":"Первичные ключи и ограничения уникальности","D":"Внешние ключи между таблицами каталога"}'::jsonb, 'C', 'Большинство таблиц каталога использует в качестве первичного ключа столбец oid.', '{"A":"Триггеров на таблицах каталога нет.","B":"Таблицы каталога не секционируются.","C":"Так сказано в курсе.","D":"Об этом в курсе речи нет: появились первичные ключи и ограничения уникальности."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '09.'), 'Как правильно изменять содержимое системного каталога?', '{"A":"Командами psql вроде \\d","B":"Правкой файла postgresql.conf","C":"Командами DDL: CREATE, ALTER, DROP","D":"Прямыми командами INSERT и UPDATE в таблицы pg_*"}'::jsonb, 'C', 'Читать каталог можно обычными запросами SELECT.', '{"A":"Эти команды только показывают содержимое каталога.","B":"В нём хранятся параметры конфигурации, а не описание объектов.","C":"Они согласованно меняют описание объектов в каталоге.","D":"Прямые изменения не рекомендуются и могут нарушить целостность каталога."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '09.'), 'Что выводит команда psql \d pg_class?', '{"A":"Права доступа к pg_class","B":"Описание объекта pg_class: столбцы, их типы и индексы","C":"Только размер таблицы pg_class","D":"Содержимое таблицы pg_class"}'::jsonb, 'B', 'С модификатором + выводится подробное описание.', '{"A":"Права доступа показывает команда \\dp.","B":"\\d от слова describe.","C":"Размер показывают подробные списки, например \\dt+.","D":"Строки таблицы выводит запрос SELECT."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '09.'), 'Почему не рекомендуется создавать собственные объекты с именами на pg_?', '{"A":"Чтобы избежать конфликтов имён с объектами системного каталога","B":"Такие имена запрещены для любых объектов","C":"Такие объекты не попадают в резервные копии","D":"Такие объекты автоматически становятся общими для кластера"}'::jsonb, 'A', 'Столбцы таблиц каталога имеют свой трёхбуквенный префикс.', '{"A":"Все таблицы и представления каталога начинаются с pg_.","B":"Для таблиц они разрешены, хотя и не рекомендуются; для схем и табличных пространств префикс pg_ зарезервирован.","C":"Префикс имени на резервное копирование не влияет.","D":"Общие объекты определяются устройством каталога, а не именем."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '09.'), 'Что верно для системного каталога?', '{"A":"Он хранится в самом кластере в виде таблиц и представлений","B":"Он хранится в файле postgresql.conf","C":"Его можно читать обычными запросами SELECT","D":"Он полностью общий для всех баз кластера"}'::jsonb, 'AC', 'Основная схема каталога — pg_catalog, альтернативное представление — information_schema.', '{"A":"Это метаинформация о кластере внутри кластера.","B":"В этом файле хранятся параметры конфигурации.","C":"Клиентские программы так и получают описание объектов.","D":"Общая лишь часть таблиц, остальные есть в каждой базе."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '09.'), 'Какой тип reg* соответствует таблице pg_class?', '{"A":"`regproc`","B":"`regrole`","C":"`regclass`","D":"`regtype`"}'::jsonb, 'C', 'Типы reg* — псевдонимы oid для некоторых таблиц каталога.', '{"A":"Соответствует функциям (pg_proc).","B":"Соответствует ролям.","C":"Преобразует имя отношения в oid и обратно.","D":"Соответствует типам данных (pg_type)."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '09.'), 'Допишите запрос, чтобы по oid 1259 получить имя соответствующей таблицы:
```
SELECT 1259::___;
```', '{"A":"`text`","B":"`regclass`","C":"`oid`","D":"`regtype`"}'::jsonb, 'B', 'Обратное преобразование: ''pg_class''::regclass::oid.', '{"A":"Получится строка с числом, а не имя таблицы.","B":"Приведение oid к regclass выводит имя отношения, здесь pg_class.","C":"Число останется числом.","D":"Ищет тип данных с таким oid; типа с oid 1259 нет, поэтому выведется само число."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '10.'), 'Допишите команду из практики курса, чтобы шаблон template1 хранился в табличном пространстве ts:
```
ALTER DATABASE template1 SET ___ ts;
```', '{"A":"`TABLESPACE`","B":"`DEFAULT`","C":"`STORAGE`","D":"`LOCATION`"}'::jsonb, 'A', 'Пока к перемещаемой базе есть подключения, команда не выполнится.', '{"A":"Меняет табличное пространство по умолчанию для базы; новые базы из этого шаблона его унаследуют.","B":"Такой формы у ALTER DATABASE нет.","C":"Такой формы у ALTER DATABASE нет.","D":"Указывает каталог при создании табличного пространства."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '10.'), 'Что нужно, чтобы удалить табличное пространство командой DROP TABLESPACE?', '{"A":"В нём не должно оставаться объектов","B":"Остановить сервер","C":"Предварительно удалить его каталог вручную","D":"Удалить все базы кластера"}'::jsonb, 'A', 'В практике курса созданное табличное пространство в конце удаляют.', '{"A":"Непустое табличное пространство удалить нельзя.","B":"Команда выполняется на работающем сервере.","C":"Вручную трогать файлы табличного пространства нельзя.","D":"Достаточно, чтобы в этом пространстве не было объектов."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '10.'), 'Что представляет собой табличное пространство по сути?', '{"A":"Логическую группу объектов, как схема","B":"Отдельный экземпляр сервера","C":"Один файл, в котором лежат все таблицы","D":"Указание на каталог файловой системы, где располагаются данные"}'::jsonb, 'D', 'Для пользовательских пространств в PGDATA/pg_tblspc создаются символические ссылки.', '{"A":"Логическое (схемы) и физическое (табличные пространства) разделения независимы.","B":"Табличные пространства — часть одного кластера.","C":"Каждый объект хранится в своих файлах внутри каталога.","D":"Так сказано в курсе."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '10.'), 'Почему внутри PGDATA/global нет подкаталогов баз данных?', '{"A":"Базы там хранятся в одном общем файле","B":"Данные в нём относятся ко всему кластеру, а не к отдельным базам","C":"Это каталог журнала предзаписи","D":"Подкаталоги создаются только после первого подключения"}'::jsonb, 'B', 'В PGDATA/base данные, наоборот, разложены по подкаталогам баз.', '{"A":"Объекты хранятся в отдельных файлах, а здесь лежат только общие объекты.","B":"Это табличное пространство pg_global с общими объектами каталога.","C":"Журнал находится в PGDATA/pg_wal.","D":"Такой зависимости нет."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '10.'), 'Что задают параметры seq_page_cost и random_page_cost?', '{"A":"Размер буферного кеша","B":"Стоимость хранения данных на диске","C":"Примерную стоимость чтения страницы при последовательном и произвольном доступе — для планировщика","D":"Предельную скорость чтения с диска"}'::jsonb, 'C', 'Их подробно рассматривают в курсе QPT «Оптимизация запросов».', '{"A":"Это параметр shared_buffers.","B":"Речь об оценке стоимости чтения, а не хранения.","C":"Их можно задать и для отдельного табличного пространства.","D":"Параметры меняют только оценки планировщика, а не работу дисков."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '10.'), 'Что будет, если для табличного пространства уменьшить random_page_cost относительно seq_page_cost?', '{"A":"Планировщик будет чаще выбирать последовательное сканирование","B":"Ничего не изменится","C":"Чтение с диска станет быстрее","D":"Планировщик будет чаще выбирать индексный доступ"}'::jsonb, 'D', 'В практике курса для pg_default задают random_page_cost = 1.1.', '{"A":"Наоборот: произвольное чтение будет казаться дешевле.","B":"Изменятся оценки стоимости произвольного чтения, а это может повлиять на выбор плана.","C":"Параметр меняет только оценки планировщика.","D":"Чем меньше соотношение параметров, тем чаще индексный доступ предпочтительнее последовательного."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '10.'), 'Какие параметры можно задать для табличного пространства командой ALTER TABLESPACE … SET?', '{"A":"`seq_page_cost`","B":"`work_mem`","C":"`random_page_cost`","D":"`shared_buffers`"}'::jsonb, 'AC', 'Так можно учесть, что пространства лежат на дисках разной скорости.', '{"A":"Оценка стоимости последовательного чтения страницы.","B":"Задаётся для экземпляра, базы, роли или сеанса, но не для табличного пространства.","C":"Оценка стоимости произвольного чтения страницы.","D":"Задаётся для всего экземпляра и требует перезапуска."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '10.'), 'Как объекты хранятся внутри каталога табличного пространства?', '{"A":"Все объекты базы — в одном файле","B":"Каждый объект — в своих отдельных файлах","C":"По одному файлу на схему","D":"Все таблицы пространства — в одном файле"}'::jsonb, 'B', 'Подробнее о файлах объектов — в теме о низкоуровневом хранении.', '{"A":"Каждый объект хранится отдельно.","B":"В пользовательском табличном пространстве файлы лежат в подкаталогах версии сервера и базы данных.","C":"Схемы на физическое хранение не влияют.","D":"Каждый объект хранится отдельно."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '10.'), 'Допишите команду, чтобы табличное пространство ts стало пространством по умолчанию для новой базы appdb:
```
CREATE DATABASE appdb ___ ts;
```', '{"A":"`TABLESPACE`","B":"`IN`","C":"`LOCATION`","D":"`DEFAULT`"}'::jsonb, 'A', 'Без указания база получает табличное пространство шаблона.', '{"A":"Задаёт табличное пространство по умолчанию для создаваемой базы.","B":"Такого предложения у CREATE DATABASE нет.","C":"Это предложение команды CREATE TABLESPACE, а не CREATE DATABASE.","D":"Такого предложения у CREATE DATABASE нет."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '11.'), 'Как называется первый файл основного слоя постоянной таблицы?', '{"A":"Именем таблицы","B":"Именем схемы и таблицы через точку","C":"Числовым идентификатором без суффикса","D":"Идентификатором с суффиксом _main"}'::jsonb, 'C', 'Основной слой содержит сами данные: версии строк или индексные записи.', '{"A":"Файлы называются по числовому идентификатору, а не по имени.","B":"Имена схем и таблиц в именах файлов не используются.","C":"Суффикс имени слоя есть только у других слоёв; следующие сегменты получают окончания .1, .2 и далее.","D":"Суффиксы бывают у других слоёв: _fsm, _vm, _init."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '11.'), 'Как называется второй файл-сегмент основного слоя, если первый называется NNN?', '{"A":"`NNN.1`","B":"`NNN.seg1`","C":"`NNN_1`","D":"`NNN_main`"}'::jsonb, 'A', 'Новый сегмент создаётся, когда файл дорастает до 1 ГБ.', '{"A":"Порядковый номер сегмента добавляется в конец имени через точку.","B":"Номер сегмента добавляется без слова seg.","C":"Через подчёркивание добавляется имя слоя, а не номер сегмента.","D":"Суффикса _main не существует."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '11.'), 'Какого слоя не бывает у индекса?', '{"A":"Карты видимости (vm)","B":"Слоя init","C":"Основного слоя","D":"Карты свободного пространства (fsm)"}'::jsonb, 'A', 'Карта видимости отмечает страницы, где все версии строк видны всем, и нужна только таблицам.', '{"A":"Карта видимости есть только у таблиц.","B":"Он есть у индексов нежурналируемых таблиц.","C":"Основной слой с индексными записями есть у каждого индекса, хранимого на диске.","D":"У индекса она может быть: в ней отмечаются освободившиеся страницы."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '11.'), 'Почему важно, что файлы всех объектов одной базы и одного табличного пространства лежат в одном каталоге?', '{"A":"Файловые системы могут плохо работать с очень большим числом файлов в каталоге","B":"PostgreSQL блокирует весь каталог при записи","C":"Резервное копирование одного каталога невозможно","D":"Каталог может вместить не больше 1 ГБ данных"}'::jsonb, 'A', 'Одному объекту на диске может соответствовать несколько файлов.', '{"A":"Это нужно учитывать при большом числе объектов.","B":"Такой блокировки нет.","C":"Это к расположению файлов не относится.","D":"1 ГБ — размер файла-сегмента по умолчанию (меняется при сборке), размер каталога этим не ограничен."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '11.'), 'Какое ограничение действует на размер версии строки?', '{"A":"Ограничений нет","B":"Она может занимать до 1 ГБ","C":"Она должна целиком помещаться на одну страницу","D":"Она не больше размера буферного кеша"}'::jsonb, 'C', 'Длинные значения сжимаются и/или выносятся в toast-таблицу.', '{"A":"Версия строки должна помещаться на страницу.","B":"Около 1 ГБ — предел отдельного значения поля, а хранимая версия строки должна помещаться на странице.","C":"Для длинных значений применяется TOAST.","D":"Ограничение задаёт размер страницы."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '11.'), 'Строка с длинным значением обновляется, но само длинное значение не меняется. Что происходит в toast-таблице?', '{"A":"Новая версия строки ссылается на то же значение в toast-таблице","B":"Старое значение сразу удаляется","C":"Значение переносится в основную таблицу","D":"Значение заново копируется в toast-таблицу"}'::jsonb, 'A', 'Toast-таблица читается только при обращении к длинному значению.', '{"A":"У toast-таблицы своя версионность, и это экономит место.","B":"На него продолжает ссылаться новая версия строки.","C":"Длинное значение остаётся в toast-таблице.","D":"Копирования не происходит."}'::jsonb
    UNION ALL
    SELECT (SELECT id FROM categories WHERE left(name, 3) = '11.'), 'Какая стратегия хранения по умолчанию используется для столбца типа text?', '{"A":"`plain`","B":"`extended`","C":"`main`","D":"`external`"}'::jsonb, 'B', 'Стратегию меняет команда ALTER TABLE … ALTER COLUMN … SET STORAGE.', '{"A":"Без сжатия и выноса; так хранятся типы фиксированной длины.","B":"Разрешены сжатие и вынос: сначала пробуется сжатие, затем значение может выноситься в toast-таблицу.","C":"Сжатие с выносом только в крайнем случае.","D":"Вынос без сжатия; в практике курса стратегию меняют на неё."}'::jsonb
    UNION ALL
