) AS n(category_id, question_text, options, correct_answer, explanation, option_notes)
WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.question_text = n.question_text);

DO $check$
DECLARE n integer;
BEGIN
    SELECT count(*) INTO n FROM questions WHERE option_notes IS NOT NULL AND category_id IN (SELECT id FROM categories WHERE left(name, 3) IN ('09.', '10.', '11.', '12.'));
    IF n < 45 THEN
        RAISE EXCEPTION 'Ожидалось не меньше 45 вопросов с пояснениями в темах 09–12, найдено %', n;
    END IF;
END
$check$;

COMMIT;
